const toRad = d => d * Math.PI / 180;

// San Francisco
const lat1 = 37.7749, lon1 = -122.4194;
// Boston, MA 02118
const lat2 = 42.3388, lon2 = -71.0726;

const R = 3958.8; // Earth radius in miles
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));

const miles = R * c;
const km = miles * 1.60934;

console.log('From: San Francisco, CA (37.7749, -122.4194)');
console.log('To:   4829 Elm Ridge Way, Suite 7, Boston, MA 02118 (~42.3388, -71.0726)');
console.log('');
console.log('Great-circle (straight-line) distance:');
console.log('  ' + miles.toFixed(1) + ' miles');
console.log('  ' + km.toFixed(1) + ' kilometers');
"
